package com.inventoryhighlighter;

import javax.inject.Singleton;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;

@Singleton
// Stores widget identity for the currently hovered item so duplicate item IDs in different slots stay distinct.
public class HoverState
{
    private int componentId = -1;
    private int slotIndex = -1;
    private int itemId = -1;

    public void setHoveredItem(int componentId, int slotIndex, int itemId)
    {
        this.componentId = componentId;
        this.slotIndex = slotIndex;
        this.itemId = itemId;
    }

    public boolean isItemHovered(WidgetItem item)
    {
        if (item == null || componentId == -1 || slotIndex == -1 || itemId == -1)
        {
            return false;
        }

        Widget widget = item.getWidget();
        return widget != null
            && widget.getId() == componentId
            && widget.getIndex() == slotIndex
            && item.getId() == itemId;
    }

    public boolean isSet()
    {
        return componentId != -1 && slotIndex != -1 && itemId != -1;
    }

    public int getComponentId()
    {
        return componentId;
    }

    public int getSlotIndex()
    {
        return slotIndex;
    }

    public int getItemId()
    {
        return itemId;
    }

    public void clear()
    {
        componentId = -1;
        slotIndex = -1;
        itemId = -1;
    }
}

package com.inventoryhighlighter;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;

@Singleton
public class InteractionTracker
{
    public static final int CAP_NONE = 0;
    public static final int CAP_EAT = 1;
    public static final int CAP_DRINK = 2;

    private static final class Mark
    {
        private final int itemId;
        private final int markTick;
        private final int markCycle;
        private final int capGroup;

        private Mark(int itemId, int markTick, int markCycle, int capGroup)
        {
            this.itemId = itemId;
            this.markTick = markTick;
            this.markCycle = markCycle;
            this.capGroup = capGroup;
        }
    }

    private final Client client;
    private final InventoryHighlighterConfig config;
    private final Map<Long, Mark> marks = new HashMap<>();

    @Inject
    private InteractionTracker(Client client, InventoryHighlighterConfig config)
    {
        this.client = client;
        this.config = config;
    }

    private static long key(int componentId, int slotIndex)
    {
        return (((long) componentId) << 32) | (slotIndex & 0xffffffffL);
    }

    // Min display time in client ticks (~20ms each).
    private int rolloverCycles()
    {
        return Math.round(config.interactRolloverMs() / (float) Constants.CLIENT_TICK_LENGTH);
    }

    // Eat/Drink keep only the latest mark per group; the game consumes the last-clicked.
    void mark(int componentId, int slotIndex, int itemId, int capGroup)
    {
        if (capGroup != CAP_NONE)
        {
            marks.values().removeIf(m -> m.capGroup == capGroup);
        }

        marks.put(key(componentId, slotIndex), new Mark(itemId, client.getTickCount(), client.getGameCycle(), capGroup));
    }

    // Lit during the click tick, then into the next tick until the min display time elapses. The itemId match stops a
    // client-side swap (e.g. Instant Inventory) inheriting the outline it replaced.
    boolean isActive(WidgetItem widgetItem)
    {
        if (widgetItem == null || marks.isEmpty())
        {
            return false;
        }

        Widget widget = widgetItem.getWidget();
        if (widget == null)
        {
            return false;
        }

        Mark m = marks.get(key(widget.getId(), widget.getIndex()));
        if (m == null || m.itemId != widgetItem.getId())
        {
            return false;
        }

        int currentTick = client.getTickCount();
        if (m.markTick == currentTick)
        {
            return true;
        }

        int rollover = rolloverCycles();
        return rollover > 0
            && currentTick == m.markTick + 1
            && client.getGameCycle() - m.markCycle < rollover;
    }

    // Drop marks past their window (one extra tick when a min display time is set).
    void expireStale()
    {
        if (marks.isEmpty())
        {
            return;
        }

        int currentTick = client.getTickCount();
        int maxAge = rolloverCycles() > 0 ? 1 : 0;
        marks.values().removeIf(m -> currentTick - m.markTick > maxAge);
    }

    void clear()
    {
        marks.clear();
    }
}

package com.inventoryhighlighter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Alpha;
import java.awt.Color;

@ConfigGroup(InventoryHighlighterConfig.GROUP)
// RuneLite stores user edits by config key; these defaults are used only until a key is changed or reset.
public interface InventoryHighlighterConfig extends Config
{
    String GROUP = "inventoryhighlighter";
    String DEFAULT_ITEM_LIST = "Saradomin brew*, *moonlight antelope, Marlin, Manta ray, Anglerfish, Shark, *karambw*, Prayer potion*, Super restore*, *combat potion*, *Ranging potion*";
    String DEFAULT_NOTEPAD_TEXT = "Use this as a quick copy/paste text storage area for item lists or notes. It does not affect highlighting.";
    String HELP_TEXT = "Enter item names in Item List, separated by commas. Highlight mode decides whether the list is a whitelist (highlight only these items) or a blacklist (highlight everything except these items). Plain names match exact items only, so Shark matches Shark but not Raw shark. Use * as a wildcard: Sha* matches names starting with Sha, *ar matches names ending in ar, and *ar* matches names containing ar.";

    @ConfigSection(
        name = "How to use",
        description = "Instructions and wildcard examples",
        position = 100,
        closedByDefault = true
    )
    String helpSection = "help";

    // The item list is shared by both modes; Highlight mode decides whether it acts as a whitelist or a blacklist.
    // Highlighting is intentionally hover-only; drawing every matching item was only useful during performance tuning.

    @ConfigItem(
        keyName = "itemList",
        name = "Item List",
        description = "Comma-separated item names. Shared by both modes: highlighted in Whitelist mode, ignored in Blacklist mode.",
        position = 1
    )
    default String itemList()
    {
        return DEFAULT_ITEM_LIST;
    }

    @ConfigItem(
        keyName = "highlightMode",
        name = "Highlight mode",
        description = "Whitelist highlights only the items in the list. Blacklist highlights every item except those in the list (an empty list highlights everything).",
        position = 2
    )
    default HighlightMode highlightMode()
    {
        return HighlightMode.WHITELIST;
    }

    @Alpha
    @ConfigItem(
        keyName = "outlineColor",
        name = "Outline Color",
        description = "The color of the outline",
        position = 3
    )
    default Color outlineColor()
    {
        return Color.RED;
    }

    @Alpha
    @ConfigItem(
        keyName = "fillColor",
        name = "Fill Color",
        description = "The color of the fill",
        position = 4
    )
    default Color fillColor()
    {
        return new Color(255, 0, 0, 50);
    }

    @ConfigItem(
        keyName = "showInteract",
        name = "Show interact",
        description = "Recolor a highlighted item's outline while you interact with it (eat/drink/wear/use/fletch/etc.).",
        position = 5
    )
    default boolean showInteract()
    {
        return false;
    }

    @Alpha
    @ConfigItem(
        keyName = "interactColor",
        name = "Interact Color",
        description = "The outline color shown while interacting with a highlighted item",
        position = 6
    )
    default Color interactColor()
    {
        return new Color(0, 255, 0, 180);
    }

    @Range(
        min = 0,
        max = 600
    )
    @ConfigItem(
        keyName = "interactRolloverMs",
        name = "Interact min. display (ms)",
        description = "Minimum time (ms) the interact outline stays lit. 0 = only the tick you clicked.",
        position = 7
    )
    default int interactRolloverMs()
    {
        return 0;
    }

    @ConfigItem(
        keyName = "outlineThickness",
        name = "Outline Thickness",
        description = "The thickness of the outline in pixels (doesn't work with sprite outlines)",
        position = 8
    )
    default int outlineThickness()
    {
        return 2;
    }

    @ConfigItem(
        keyName = "outlineOnly",
        name = "Outline Only",
        description = "Only show outline instead of filled highlight",
        position = 9
    )
    default boolean outlineOnly()
    {
        return false;
    }

    @ConfigItem(
        keyName = "spriteOnly",
        name = "Sprite Only",
        description = "Highlight only the item sprite instead of the full clickbox",
        position = 10
    )
    default boolean spriteOnly()
    {
        return true;
    }

    @ConfigItem(
        keyName = "presets",
        name = "List Notepad",
        description = "Optional text storage area for quick copy/paste of item lists or notes. This field does not affect highlighting directly.",
        position = 99
    )
    default String presets()
    {
        return DEFAULT_NOTEPAD_TEXT;
    }

    @ConfigItem(
        keyName = "helpText",
        name = "Guide",
        description = "Quick reference for item names and wildcard matching",
        position = 101,
        section = helpSection
    )
    default String helpText()
    {
        return HELP_TEXT;
    }

    // Shared by both modes; the mode decides whether a list match means "highlight" (whitelist) or "suppress" (blacklist).
    enum HighlightMode
    {
        WHITELIST,
        BLACKLIST;

        @Override
        public String toString()
        {
            // Render as "Whitelist" / "Blacklist" in the config dropdown instead of the all-caps enum name.
            return name().charAt(0) + name().substring(1).toLowerCase();
        }
    }
}

package com.inventoryhighlighter;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
// Renders the highlighted item and caches expensive item-name and filled-sprite lookups.
public class InventoryHighlighterOverlay extends WidgetItemOverlay
{
    private final Client client;
    private final InventoryHighlighterConfig config;
    private final ItemManager itemManager;
    private final HoverState hoverState;
    private final InteractionTracker interactionTracker;
    private final Cache<FillKey, Image> fillCache;

    private final Map<String, Boolean> itemPatterns = new HashMap<>();
    private final Map<String, Pattern> wildcardPatterns = new HashMap<>();
    private final Set<Integer> matchedItemIds = new HashSet<>();
    private final Map<Integer, Boolean> itemMatchCache = new HashMap<>();

    private String lastConfigList = "";

    private static final class FillKey
    {
        private final int itemId;
        private final int quantity;
        private final int color;

        private FillKey(int itemId, int quantity, Color color)
        {
            this.itemId = itemId;
            this.quantity = quantity;
            this.color = color.getRGB();
        }

        @Override
        public boolean equals(Object other)
        {
            if (this == other)
            {
                return true;
            }

            if (!(other instanceof FillKey))
            {
                return false;
            }

            FillKey fillKey = (FillKey) other;
            return itemId == fillKey.itemId
                && quantity == fillKey.quantity
                && color == fillKey.color;
        }

        @Override
        public int hashCode()
        {
            int result = itemId;
            result = 31 * result + quantity;
            result = 31 * result + color;
            return result;
        }
    }

    @Inject
    private InventoryHighlighterOverlay(Client client, InventoryHighlighterConfig config,
        ItemManager itemManager, HoverState hoverState, InteractionTracker interactionTracker)
    {
        this.client = client;
        this.config = config;
        this.itemManager = itemManager;
        this.hoverState = hoverState;
        this.interactionTracker = interactionTracker;
        this.fillCache = CacheBuilder.newBuilder()
            .concurrencyLevel(1)
            .maximumSize(64)
            .build();

        showOnInventory();
        showOnBank();
        setPriority(Overlay.PRIORITY_LOW);

        updateHighlightPatterns(config.itemList());
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (client.getGameState() != GameState.LOGGED_IN || widgetItem == null || itemManager == null)
        {
            return;
        }

        boolean clickActive = config.showInteract() && interactionTracker.isActive(widgetItem);
        boolean hovered = hoverState.isItemHovered(widgetItem);

        if (!clickActive && !hovered)
        {
            return;
        }

        if (!clickActive && !shouldHighlightItem(itemId))
        {
            return;
        }

        Color outlineColor = clickActive ? config.interactColor() : config.outlineColor();
        Color fillColor = clickActive ? config.interactColor() : config.fillColor();
        boolean outlineOnly = clickActive || config.outlineOnly();
        drawHighlight(graphics, itemId, widgetItem, outlineColor, fillColor, outlineOnly);
    }

    public boolean shouldHighlightItem(int itemId)
    {
        boolean listed = isListed(itemId);
        // Blacklist inverts the raw match; an empty list means nothing is listed, so everything highlights.
        return config.highlightMode() == InventoryHighlighterConfig.HighlightMode.BLACKLIST
            ? !listed
            : listed;
    }

    // Raw, mode-agnostic match: does this item's name match one of the configured patterns?
    // The cache is keyed on this result, so toggling whitelist/blacklist never invalidates it.
    private boolean isListed(int itemId)
    {
        if (itemPatterns.isEmpty())
        {
            return false;
        }

        if (matchedItemIds.contains(itemId))
        {
            return true;
        }

        Boolean cachedMatch = itemMatchCache.get(itemId);
        if (cachedMatch != null)
        {
            return cachedMatch;
        }

        boolean matches = isItemMatch(itemId);
        itemMatchCache.put(itemId, matches);
        if (matches)
        {
            matchedItemIds.add(itemId);
        }
        return matches;
    }

    private boolean isItemMatch(int itemId)
    {
        // Plain entries are exact names; entries containing '*' use anchored wildcard matching.
        try
        {
            ItemComposition itemDef = itemManager.getItemComposition(itemId);
            if (itemDef == null || itemDef.getName() == null)
            {
                return false;
            }

            String itemName = Text.standardize(itemDef.getName()).toLowerCase();
            for (Map.Entry<String, Boolean> entry : itemPatterns.entrySet())
            {
                String pattern = entry.getKey();
                boolean isWildcard = entry.getValue();
                Pattern wildcardPattern = wildcardPatterns.get(pattern);
                if (isWildcard ? wildcardPattern.matcher(itemName).matches() : itemName.equals(pattern))
                {
                    return true;
                }
            }
        }
        catch (Exception e)
        {
            log.debug("Error matching item {}: {}", itemId, e.getMessage());
        }

        return false;
    }

    private void updateHighlightPatterns(String configList)
    {
        // Rebuild pattern caches only when the config string changes.
        String standardizedConfig = configList == null ? "" : Text.standardize(configList).toLowerCase();
        if (standardizedConfig.equals(lastConfigList))
        {
            return;
        }

        lastConfigList = standardizedConfig;
        itemPatterns.clear();
        wildcardPatterns.clear();
        matchedItemIds.clear();
        itemMatchCache.clear();

        if (standardizedConfig.isEmpty())
        {
            return;
        }

        for (String rawPattern : standardizedConfig.split(","))
        {
            String pattern = rawPattern.trim();
            if (pattern.isEmpty())
            {
                continue;
            }

            boolean isWildcard = pattern.indexOf('*') != -1;
            itemPatterns.put(pattern, isWildcard);
            if (isWildcard)
            {
                wildcardPatterns.put(pattern, Pattern.compile(toWildcardRegex(pattern)));
            }
        }
    }

    private static String toWildcardRegex(String pattern)
    {
        String[] parts = pattern.split("\\*", -1);
        StringBuilder regex = new StringBuilder("^");
        for (int i = 0; i < parts.length; i++)
        {
            regex.append(Pattern.quote(parts[i]));
            if (i < parts.length - 1)
            {
                regex.append(".*");
            }
        }
        regex.append('$');
        return regex.toString();
    }

    private void drawHighlight(Graphics2D graphics, int itemId, WidgetItem widgetItem, Color outlineColor, Color fillColor, boolean outlineOnly)
    {
        // Sprite mode mirrors Inventory Tags: use ItemManager outlines and ImageUtil fills instead of custom canvas tracing.
        Rectangle bounds = widgetItem.getCanvasBounds();
        if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
        {
            return;
        }

        Color originalColor = graphics.getColor();
        Stroke originalStroke = graphics.getStroke();

        try
        {
            if (config.spriteOnly())
            {
                if (!outlineOnly)
                {
                    Image filledImage = getFillImage(itemId, widgetItem.getQuantity(), fillColor);
                    graphics.drawImage(filledImage, (int) bounds.getX(), (int) bounds.getY(), null);
                }

                BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), outlineColor);
                if (outline != null)
                {
                    graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
                }
                return;
            }

            if (!outlineOnly)
            {
                graphics.setColor(new Color(
                    fillColor.getRed(),
                    fillColor.getGreen(),
                    fillColor.getBlue(),
                    Math.min(fillColor.getAlpha(), 130)));
                graphics.fill(bounds);
            }

            graphics.setColor(outlineColor);
            graphics.setStroke(new BasicStroke(config.outlineThickness()));
            graphics.draw(bounds);
        }
        catch (Exception e)
        {
            log.debug("Error drawing highlight: {}", e.getMessage(), e);
        }
        finally
        {
            graphics.setColor(originalColor);
            graphics.setStroke(originalStroke);
        }
    }

    private Image getFillImage(int itemId, int quantity, Color fillColor)
    {
        FillKey key = new FillKey(itemId, quantity, fillColor);
        Image image = fillCache.getIfPresent(key);
        if (image == null)
        {
            image = ImageUtil.fillImage(itemManager.getImage(itemId, quantity, false), fillColor);
            fillCache.put(key, image);
        }
        return image;
    }

    public void clearCache()
    {
        // null can never equal the (never-null) standardized config, so updateHighlightPatterns always rebuilds -
        // including when the list is cleared to empty. Using "" here would collide with an empty list and skip the rebuild.
        lastConfigList = null;
        fillCache.invalidateAll();
        updateHighlightPatterns(config.itemList());
    }
}

package com.inventoryhighlighter;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
    name = "Inventory Hover Highlighter",
    description = "Highlights specified items in your inventory",
    tags = {"inventory", "highlight", "items", "overlay", "tagging"}
)
// Coordinates plugin lifecycle and turns RuneLite menu-hover events into a specific hovered widget item.
public class InventoryHighlighterPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private InventoryHighlighterOverlay overlay;

    @Inject
    private HoverState hoverState;

    @Inject
    private InventoryHighlighterConfig config;

    @Inject
    private InteractionTracker interactionTracker;

    private String lastItemListValue = "";

    @Override
    protected void startUp()
    {
        log.debug("InventoryHighlighter started");
        lastItemListValue = config.itemList();
        hoverState.clear();
        interactionTracker.clear();
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        hoverState.clear();
        interactionTracker.clear();
        log.debug("InventoryHighlighter stopped");
    }

    @Provides
    InventoryHighlighterConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(InventoryHighlighterConfig.class);
    }

    @Subscribe
    public void onPostMenuSort(PostMenuSort event)
    {
        // PostMenuSort is the hover-change signal while the right-click menu is closed; keep the last hover while it is open.
        if (client.isMenuOpen())
        {
            return;
        }

        MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
        if (menuEntries.length == 0)
        {
            hoverState.clear();
            return;
        }

        updateHoveredItem(menuEntries[menuEntries.length - 1]);
    }

    private void updateHoveredItem(MenuEntry menuEntry)
    {
        // Menu entries identify the hovered widget slot, so duplicate items are distinguished by slot instead of item ID alone.
        Widget widget = menuEntry.getWidget();
        if (!isSupportedItemWidget(widget))
        {
            hoverState.clear();
            return;
        }

        int itemId = widget.getItemId();
        int slotIndex = widget.getIndex();
        if (slotIndex == -1)
        {
            slotIndex = menuEntry.getParam0();
        }

        if (itemId == -1 || slotIndex == -1 || !overlay.shouldHighlightItem(itemId))
        {
            hoverState.clear();
            return;
        }

        hoverState.setHoveredItem(widget.getId(), slotIndex, itemId);
    }

    private boolean isSupportedItemWidget(Widget widget)
    {
        // Limit hover tracking to inventory-like interfaces that WidgetItemOverlay also renders over.
        if (widget == null || widget.getItemId() == -1)
        {
            return false;
        }

        int componentId = widget.getId();
        int interfaceId = WidgetUtil.componentToInterface(componentId);
        return componentId == InterfaceID.Inventory.ITEMS
            || componentId == InterfaceID.Bankmain.ITEMS
            || componentId == InterfaceID.SharedBank.ITEMS
            || interfaceId == InterfaceID.INVENTORY
            || interfaceId == InterfaceID.BANKMAIN
            || interfaceId == InterfaceID.BANKSIDE
            || interfaceId == InterfaceID.SHARED_BANK
            || interfaceId == InterfaceID.SHARED_BANK_SIDE
            || interfaceId == InterfaceID.BANK_DEPOSITBOX
            || interfaceId == InterfaceID.SHOPSIDE
            || interfaceId == InterfaceID.GE_OFFERS_SIDE
            || interfaceId == InterfaceID.GE_PRICECHECKER_SIDE
            || interfaceId == InterfaceID.EQUIPMENT_SIDE
            || interfaceId == InterfaceID.SEED_VAULT_DEPOSIT
            || interfaceId == InterfaceID.TRADEMAIN
            || interfaceId == InterfaceID.TRADESIDE
            || interfaceId == InterfaceID.POH_COSTUMES_SIDE;
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() != InventoryID.INV && event.getContainerId() != InventoryID.BANK)
        {
            return;
        }

        hoverState.clear();
        overlay.clearCache();
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        hoverState.clear();
        overlay.clearCache();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!InventoryHighlighterConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }

        String currentItemList = config.itemList();
        if (!currentItemList.equals(lastItemListValue))
        {
            lastItemListValue = currentItemList;
        }

        hoverState.clear();
        overlay.clearCache();
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!config.showInteract())
        {
            return;
        }

        String option = event.getMenuOption();
        if (option == null)
        {
            return;
        }

        option = Text.removeTags(option);
        if ("Cancel".equalsIgnoreCase(option))
        {
            return;
        }

        // Identity comes from the clicked event widget, not the live hover, which can advance to another item before
        // this fires. Fall back to the hover for actions whose event widget isn't the item (e.g. use-on).
        int component;
        int slotIndex;
        int itemId;
        Widget widget = event.getWidget();
        if (isSupportedItemWidget(widget) && overlay.shouldHighlightItem(widget.getItemId()))
        {
            component = widget.getId();
            slotIndex = widget.getIndex() == -1 ? event.getParam0() : widget.getIndex();
            itemId = widget.getItemId();
        }
        else if (hoverState.isSet())
        {
            component = hoverState.getComponentId();
            slotIndex = hoverState.getSlotIndex();
            itemId = hoverState.getItemId();
        }
        else
        {
            return;
        }

        if (slotIndex == -1)
        {
            return;
        }

        int capGroup = "Eat".equalsIgnoreCase(option) ? InteractionTracker.CAP_EAT
            : "Drink".equalsIgnoreCase(option) ? InteractionTracker.CAP_DRINK
            : InteractionTracker.CAP_NONE;

        interactionTracker.mark(component, slotIndex, itemId, capGroup);
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        interactionTracker.expireStale();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            interactionTracker.clear();
        }
    }
}

